svg.script:
const BASE = "https:/" + "/cdn.jsdelivr.net/gh/pkalogiros/AudioMass@production/src/";
const frame = document.getElementById("daw_frame");

const storageShim = `<base href="${BASE}" /><script>
  (function() {
    function makeMemStorage() {
      const mem = {};
      return {
        getItem: k => Object.prototype.hasOwnProperty.call(mem, k) ? mem[k] : null,
        setItem: (k, v) => { mem[k] = String(v); },
        removeItem: k => { delete mem[k]; },
        clear: () => { for (const k in mem) delete mem[k]; }
      };
    }
    try { window.localStorage.getItem("t"); } catch (e) {
      Object.defineProperty(window, "localStorage", { value: makeMemStorage() });
    }
    try { window.sessionStorage.getItem("t"); } catch (e) {
      Object.defineProperty(window, "sessionStorage", { value: makeMemStorage() });
    }
    try { document.cookie; } catch (e) {
      let c = "";
      Object.defineProperty(document, "cookie", { get: () => c, set: v => { c = v; } });
    }
    try { window.indexedDB; } catch (e) {
      Object.defineProperty(window, "indexedDB", { value: null });
    }
  })();
<\/script>`;

fetch(BASE + "index.html")
  .then(res => res.text())
  .then(html => {
    const injected = html.replace(/<head[^>]*>/i, match => match + storageShim);
    const win = frame.contentWindow;
    const doc = frame.contentDocument || win.document;
    doc.open();
    doc.write(injected);
    doc.close();
  });
